const cfg = $('Construir Configuración del Agente').first().json;
const subOutput = $json;

const raw =
  subOutput.respuesta ??
  subOutput.answer ??
  subOutput.output ??
  '';

const usage = subOutput.usage ?? null;

const citations =
  subOutput.citas ??
  subOutput.citations ??
  [];

const updatedHistory =
  subOutput.updated_history ??
  subOutput.conversation_history ??
  null;

const hasContext =
  subOutput.has_context ??
  subOutput.hasContext ??
  false;

const startTime = cfg._startTime || Date.now();

const baseResponse = {
  success: true,
  mode: cfg.requestedMode,
  conversationId: cfg.conversationId,
  studentId: cfg.studentId,
  cursoId: cfg.cursoId,
  answer: raw,
  citations,
  usage,
  updatedHistory,
  hasContext,
  processingTimeMs: Date.now() - startTime,
  timestamp: new Date().toISOString()
};


// =====================================================
// MODO RECURSOS
// =====================================================

if (cfg.requestedMode === 'recursos') {

  let resource = null;
  let parseError = false;

  // ---------------------------------------------------
  // CASO 1:
  // El workflow generador ya devolvió la estructura
  // ---------------------------------------------------

  if (
    subOutput.graphic !== undefined ||
    subOutput.mermaid_code !== undefined
  ) {

    const graphic =
      subOutput.graphic ??
      subOutput.mermaid_code ??
      null;

    const diagramType =
      subOutput.diagramType ??
      subOutput.mermaid_type ??
      'unknown';

    const title =
      subOutput.title ??
      'Recurso visual';

    if (graphic) {
      resource = {
        graphic,
        diagramType,
        title
      };
    }

  }

  // ---------------------------------------------------
  // CASO 2:
  // El agente devolvió JSON dentro de output/answer
  // ---------------------------------------------------

  else {

    try {

      let parsed = raw;

      if (typeof raw === 'string') {

        // Intento directo
        try {
          parsed = JSON.parse(raw);
        } catch {

          // Buscar JSON embebido
          const match = raw.match(/\{[\s\S]*\}/);

          if (match) {
            parsed = JSON.parse(match[0]);
          } else {
            throw new Error('No se encontró JSON');
          }
        }
      }

      if (
        parsed &&
        typeof parsed === 'object'
      ) {

        const graphic =
          parsed.graphic ??
          parsed.mermaidCode ??
          parsed.mermaid_code ??
          null;

        const diagramType =
          parsed.diagramType ??
          parsed.mermaidType ??
          parsed.mermaid_type ??
          'unknown';

        const title =
          parsed.title ??
          'Recurso visual';

        if (graphic) {

          resource = {
            graphic,
            diagramType,
            title
          };

        } else {
          parseError = true;
        }

      } else {
        parseError = true;
      }

    } catch (error) {
      parseError = true;
    }
  }


  // ===================================================
  // RESPUESTA FINAL PARA RECURSOS
  // ===================================================

  const result = {
    ...baseResponse,
    resource
  };

  if (!resource || parseError) {

    result.success = false;

    result.error =
      'No se pudo generar el recurso en el formato esperado.';

    // Conservamos la respuesta original solamente
    // para debugging / fallback.
    result.answer = raw;
  }

  return [
    {
      json: result
    }
  ];
}


// =====================================================
// CHAT / PRACTICAR
// =====================================================

return [
  {
    json: baseResponse
  }
];

const item = $input.first();
const webhook = item.json || {};

// ============================================================
// 1. OBTENER EL PAYLOAD REAL DEL WEBHOOK
// ============================================================
//
// n8n normalmente coloca el JSON recibido por POST dentro de
// $json.body.
//
// El fallback permite que también funcione si en algún momento
// ejecutas este nodo con el payload directamente en $json.
//

const input =
  webhook.body &&
  typeof webhook.body === 'object'
    ? webhook.body
    : webhook;


// ============================================================
// 2. DATOS BÁSICOS DEL CURSO
// ============================================================

const institutionId = input.institucion_id ?? null;
const courseId = input.curso_id ?? null;

const pineconeNamespace =
  input.pinecone_namespace ||
  (
    institutionId !== null && courseId !== null
      ? `inst_${institutionId}_curso_${courseId}`
      : null
  );


// ============================================================
// 3. DATOS DE CONFIGURACIÓN DEL AGENTE
// ============================================================

const chatbotPrompt = input.chatbot_prompt || '';

const chatbotTemperature =
  typeof input.chatbot_temperature === 'number'
    ? input.chatbot_temperature
    : Number(input.chatbot_temperature) || 0.1;

const extendKnowledge = Boolean(input.extend_knowledge);

const requestedMode =
  String(input.requested_mode || 'chat')
    .trim()
    .toLowerCase();


// ============================================================
// 4. DATOS DE LA CONVERSACIÓN
// ============================================================

const studentId = input.student_id ?? null;

const conversationId =
  input.conversation_id ?? null;

const message =
  typeof input.message === 'string'
    ? input.message.trim()
    : '';


// ============================================================
// 5. IMAGEN
// ============================================================

const image = input.image || null;

const hasImage =
  !!image &&
  typeof image === 'object' &&
  typeof image.data_url === 'string' &&
  image.data_url.startsWith('data:image/');


// ============================================================
// 6. DETERMINAR SI HAY TEXTO
// ============================================================

const hasText = message.length > 0;


// ============================================================
// 7. DETERMINAR TIPO DE INPUT
// ============================================================

let inputType = 'text';

if (hasText && hasImage) {
  inputType = 'text_image';
}
else if (hasImage) {
  inputType = 'image';
}


// ============================================================
// 8. DATOS NORMALIZADOS DE LA IMAGEN
// ============================================================

const imageName = hasImage
  ? image.name || null
  : null;

const imageMimeType = hasImage
  ? image.mime_type || null
  : null;


// ============================================================
// 9. RESULTADO NORMALIZADO
// ============================================================

return [
  {
    json: {
      // Identidad del curso
      institutionId,
      courseId,
      courseName: input.curso_nombre || null,

      // RAG
      pineconeNamespace,

      // Configuración
      chatbotPrompt,
      chatbotTemperature,
      extendKnowledge,
      requestedMode,

      // Usuario / conversación
      studentId,
      conversationId,

      // Mensaje
      message,

      // Input multimodal
      inputType,
      hasText,
      hasImage,

      // Imagen
      image,
      imageName,
      imageMimeType,

      // Análisis visual
      imageAnalysis: '',
      hasImageAnalysis: false,

      // Tokens
      maxTokens: input.max_tokens ?? null
    }
  }
];

const original = $('Obtener input').first().json;

let imageAnalysis = $input.first().json.output[0].content[0].text;
imageAnalysis = imageAnalysis.trim();

return [
  {
    json: {
      ...original,

      imageAnalysis,
      hasImageAnalysis: imageAnalysis.length > 0
    }
  }
];

const item = $input.first();
const dataUrl = $input.first().json.image.data_url;

if (!dataUrl) {
  throw new Error('No se encontró imageDataUrl.');
}

const match = dataUrl.match(/^data:(image\/[^;]+);base64,(.+)$/);

if (!match) {
  throw new Error(
    'imageDataUrl no tiene un formato Data URL válido.'
  );
}

const mimeType = match[1];
const base64Data = match[2];

return [
  {
    json: {
      ...item.json,
      imageBinaryProperty: 'image'
    },
    binary: {
      image: {
        data: base64Data,
        mimeType,
        fileName: item.json.imageName || 'image',
        fileExtension: mimeType.split('/')[1] || 'bin'
      }
    }
  }
];
